import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const m=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/index.md","filePath":"concepts.md"}'),s={name:"concepts/index.md"};function i(n,e,l,c,p,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><h2 id="layer" tabindex="-1">Layer <a class="header-anchor" href="#layer" aria-label="Permalink to &quot;Layer&quot;">​</a></h2><p>A layer is the basic building block for map interactions. Each layer can have its legends, attributions, etc.</p><p>JEO supports four layer types out-of-the-box:</p><ul><li><a href="https://docs.mapbox.com/studio-manual/overview/map-styling/" target="_blank" rel="noreferrer">Mapbox styles</a></li><li><a href="https://docs.mapbox.com/help/glossary/tileset/" target="_blank" rel="noreferrer">Mapbox tilesets</a></li><li><a href="https://docs.mapbox.com/vector-tiles/reference/" target="_blank" rel="noreferrer">Mapbox vector tiles</a> (MVTs)</li><li><a href="https://en.wikipedia.org/wiki/Tiled_web_map" target="_blank" rel="noreferrer">TileLayers</a></li></ul><p>Additionally, JEO can generate custom layers using AI (see <a href="#ai-generated-map">AI-Generated Map</a>).</p><h2 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h2><p>A map is composed of one or more layers and can be associated with related geolocated posts, that&#39;ll be rendered as markers on the map.</p><p>A map post is used for reusable map interactions, that can be embedded in any post as a <a href="/docs/map-shortcode/">shortcode</a> or <a href="/docs/map-block/">Gutenberg block</a>.</p><h2 id="one-time-map" tabindex="-1">One-time Map <a class="header-anchor" href="#one-time-map" aria-label="Permalink to &quot;One-time Map&quot;">​</a></h2><p>Instead of creating a reusable map any time you want to add a map interaction, you can create and configure an inline single-use map via the <a href="/docs/one-time-map-block/">One-Time Map block</a> for Gutenberg.</p><h2 id="geolocating-posts" tabindex="-1">Geolocating Posts <a class="header-anchor" href="#geolocating-posts" aria-label="Permalink to &quot;Geolocating Posts&quot;">​</a></h2><p>Posts can be geolocated manually by searching and adding points in the Geolocation sidebar, or automatically using AI georeferencing — which analyzes the post content and suggests locations with confidence scores. See <a href="/docs/geolocating-posts/">Geolocating posts</a> and <a href="/docs/ai-georeferencing/">AI Georeferencing</a>.</p><h2 id="ai-features" tabindex="-1">AI Features <a class="header-anchor" href="#ai-features" aria-label="Permalink to &quot;AI Features&quot;">​</a></h2><p>JEO&#39;s AI features are powered by a configurable external AI provider with a built-in knowledge base (RAG), specialized agents, and structured output. See <a href="/docs/ai-in-jeo/">AI in JEO</a> for a detailed explanation of how these pieces work together.</p><h2 id="ai-generated-map" tabindex="-1">AI-Generated Map <a class="header-anchor" href="#ai-generated-map" aria-label="Permalink to &quot;AI-Generated Map&quot;">​</a></h2><p>An AI-assisted map block that generates contextual maps from a text prompt or post content, with a chat interface for refinement. It can also generate custom map layers when a Mapbox key is configured. See <a href="/docs/minimap/">Minimap</a>.</p><h2 id="story-map" tabindex="-1">Story Map <a class="header-anchor" href="#story-map" aria-label="Permalink to &quot;Story Map&quot;">​</a></h2><p>A Story Map is a scrollytelling experience: each <strong>slide</strong> has a location, layers, and text. As the reader scrolls, the map transitions between slides. See <a href="/docs/story-map/">Story Map</a>.</p><h2 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h2><p>A full-page interactive map where readers can explore geolocated stories, toggle layers from different maps, and share a customized view. See <a href="/docs/discovery/">Discovery</a>.</p><h2 id="stories-near-you" tabindex="-1">Stories Near You <a class="header-anchor" href="#stories-near-you" aria-label="Permalink to &quot;Stories Near You&quot;">​</a></h2><p>A block that displays geolocated posts closest to the reader&#39;s location, with consent-based browser geolocation and automatic fallback. See <a href="/docs/stories-near-you/">Stories Near You</a>.</p>',23)])])}const u=a(s,[["render",i]]);export{m as __pageData,u as default};
